mapper.select:
SELECT id, content, type, difficulty, tags, source, source_type, option_a, option_b, option_c, option_d, correct_answer, analysis, solution_strategy, category_id, status, created_at, updated_at FROM question WHERE status = 1 AND type != 3
AND category_id IN
#{categoryId}
AND source_type = #{sourceType}
ORDER BY id

SELECT id, content, type, difficulty, tags, source, source_type, option_a, option_b, option_c, option_d,
       correct_answer, analysis, solution_strategy, category_id, status, created_at, updated_at
FROM question
WHERE type != 3

    AND (content LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%') OR source LIKE CONCAT('%', #{keyword}, '%'))


    AND category_id IN

        #{categoryId}



    AND status = #{status}


    AND type = #{type}


    AND difficulty = #{difficulty}


    AND source_type = #{sourceType}

ORDER BY created_at DESC

SELECT COUNT(1)
FROM question
WHERE content = #{question.content}
  AND type = #{question.type}
  AND category_id = #{question.categoryId}
  AND source_type = #{question.sourceType}
  AND correct_answer = #{question.correctAnswer}


        AND source = #{question.source}


        AND (source IS NULL OR source = '')




        AND option_a = #{question.optionA}


        AND (option_a IS NULL OR option_a = '')




        AND option_b = #{question.optionB}


        AND (option_b IS NULL OR option_b = '')




        AND option_c = #{question.optionC}


        AND (option_c IS NULL OR option_c = '')




        AND option_d = #{question.optionD}


        AND (option_d IS NULL OR option_d = '')
